import{_ as a,o as r,c as i,a2 as t}from"./chunks/framework.CDpkVv68.js";const u=JSON.parse('{"title":"Syrolands Guide","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/index.md","filePath":"en/guide/index.md"}'),n={name:"en/guide/index.md"};function o(s,e,l,d,c,h){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="syrolands-guide" tabindex="-1">Syrolands Guide <a class="header-anchor" href="#syrolands-guide" aria-label="Permalink to &quot;Syrolands Guide&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><ul><li>Start with the Introduction for the world, combat, knowledge and craft pillars.</li><li>Choose a system below for a short guide, then follow its detailed design counterpart.</li><li>Check each feature’s status: approved intent, proposed mechanics and tested availability differ.</li></ul><p>A concise introduction to Syrolands for friends, testers and future players. The Lab contains accepted ideas, experiments and proposals; a system described here is not necessarily available to play.</p><h2 id="start-here" tabindex="-1">Start here <a class="header-anchor" href="#start-here" aria-label="Permalink to &quot;Start here&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/introduction.html">Introduction: a living world shaped by its people</a> introduces the design pillars before the individual systems.</p><h2 id="characters" tabindex="-1">Characters <a class="header-anchor" href="#characters" aria-label="Permalink to &quot;Characters&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/characters/progression.html">Character Progression</a> · <a href="/Syrolands-Public/en/guide/characters/skills.html">Skills, Skillcap &amp; Teachers</a> · <a href="/Syrolands-Public/en/guide/characters/techniques.html">Techniques &amp; Specializations</a> · <a href="/Syrolands-Public/en/guide/characters/character-creation.html">Character Creation &amp; Backgrounds</a> · <a href="/Syrolands-Public/en/guide/characters/stats.html">Stats Overview</a>.</p><p>These Proposed directions aim for useful early characters, meaningful specialization and responsive play; they are not confirmed live changes.</p><h2 id="combat" tabindex="-1">Combat <a class="header-anchor" href="#combat" aria-label="Permalink to &quot;Combat&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/combat/overview.html">Combat overview</a> explains the Proposed Modern direction, the Legacy alternative and local injuries, distinguishing experiments from intended gameplay.</p><p><a href="/Syrolands-Public/en/guide/combat/limbs-and-trauma.html">Limbs and Trauma</a> · <a href="/Syrolands-Public/en/guide/combat/weapons-and-damage.html">Weapons and Damage Types</a> · <a href="/Syrolands-Public/en/guide/combat/armor-and-protection.html">Armor and Protection</a> · <a href="/Syrolands-Public/en/guide/combat/targeting-and-anatomy.html">Targeted Attacks and Anatomy</a> · <a href="/Syrolands-Public/en/guide/combat/stamina-and-reactive-combat.html">Stamina and recovery</a>.</p><h2 id="magic" tabindex="-1">Magic <a class="header-anchor" href="#magic" aria-label="Permalink to &quot;Magic&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/magic/overview.html">Magery overview</a> · <a href="/Syrolands-Public/en/guide/magic/learning-spells.html">Learning spells</a> · <a href="/Syrolands-Public/en/guide/magic/memory-and-familiarity.html">Spell Memory and Familiarity</a> · <a href="/Syrolands-Public/en/guide/magic/meditation-and-concentration.html">Meditation and Concentration</a> · <a href="/Syrolands-Public/en/guide/magic/spellbooks-scrolls-and-reagents.html">Spellbooks, scrolls and reagents</a> · <a href="/Syrolands-Public/en/guide/magic/variants-and-glyphs.html">Spell variants and glyphs</a>.</p><p>The Proposed magic model separates knowledge, execution, practice and preparation. These pages do not establish live gameplay.</p><h2 id="professions" tabindex="-1">Professions <a class="header-anchor" href="#professions" aria-label="Permalink to &quot;Professions&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/professions/overview.html">Professions overview</a> introduces the Proposed redesign: crafts as part of adventuring, learning, journals, production and reputation.</p><p><a href="/Syrolands-Public/en/guide/professions/cooking.html">Cooking</a> · <a href="/Syrolands-Public/en/guide/professions/alchemy.html">Alchemy</a> · <a href="/Syrolands-Public/en/guide/professions/mining.html">Mining</a> · <a href="/Syrolands-Public/en/guide/professions/blacksmithing.html">Blacksmithing</a> · <a href="/Syrolands-Public/en/guide/professions/tailoring.html">Tailoring</a> · <a href="/Syrolands-Public/en/guide/professions/lumberjacking.html">Lumberjacking</a> · <a href="/Syrolands-Public/en/guide/professions/carpentry.html">Carpentry</a> · <a href="/Syrolands-Public/en/guide/professions/tinkering.html">Tinkering</a> · <a href="/Syrolands-Public/en/guide/professions/inscription.html">Inscription</a>. Bowmaking is a technique path within Carpentry.</p><h2 id="items" tabindex="-1">Items <a class="header-anchor" href="#items" aria-label="Permalink to &quot;Items&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/items/item-quality.html">Item Quality / Masterworks</a> explains Proposed quality categories, materials, rare traits and item history.</p><h2 id="more-systems" tabindex="-1">More systems <a class="header-anchor" href="#more-systems" aria-label="Permalink to &quot;More systems&quot;">​</a></h2><p>Player guides will grow around World and Society / Economy as source material becomes ready. These categories do not imply empty pages or approved mechanics.</p><p>For existing detailed coverage, use the <a href="/Syrolands-Public/en/game-design/">Game Design index</a>.</p><h2 id="reading-feature-status" tabindex="-1">Reading feature status <a class="header-anchor" href="#reading-feature-status" aria-label="Permalink to &quot;Reading feature status&quot;">​</a></h2><p><strong>Proposed</strong> means a candidate idea; <strong>Accepted</strong> means approved intent. <strong>Experimental</strong> marks investigations and prototypes. <strong>Implemented</strong> identifies existing code with a stated scope. Availability and verification are listed separately: implemented does not promise a live or fully tested feature. These labels describe content, not a guarantee of current availability.</p><h2 id="combat-actions-and-practice-—-proposed" tabindex="-1">Combat actions and practice — Proposed <a class="header-anchor" href="#combat-actions-and-practice-—-proposed" aria-label="Permalink to &quot;Combat actions and practice — Proposed&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/combat/legacy-and-modern.html">Legacy and Modern</a> · <a href="/Syrolands-Public/en/guide/combat/special-attacks.html">Special Attacks</a> · <a href="/Syrolands-Public/en/guide/combat/flow.html">Flow</a> · <a href="/Syrolands-Public/en/guide/combat/reach-and-spacing.html">Reach and spacing</a> · <a href="/Syrolands-Public/en/guide/characters/familiarity.html">Familiarity</a>.</p><p><a href="/Syrolands-Public/en/game-design/combat/variable-registry.html">Combat Variable Registry</a> collects definitions before numeric tuning; no new mode or action is established as playable.</p><h2 id="three-weapon-test-profile" tabindex="-1">Three-weapon test profile <a class="header-anchor" href="#three-weapon-test-profile" aria-label="Permalink to &quot;Three-weapon test profile&quot;">​</a></h2><p><a href="/Syrolands-Public/en/guide/combat/numeric-prototype.html">Longsword, Spear and War Hammer</a> now have Experimental numbers for a future prototype. They are not implemented or final balance.</p>',30)])])}const p=a(n,[["render",o]]);export{u as __pageData,p as default};
